sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    'use strict';

    // PARAMETER ORDER IS oldValue SECOND, newValue THIRD. This is the
    // platform's calling convention, and it was measured on this release
    // rather than assumed, because getting it wrong is silent: an
    // earlier revision of this script declared (control, newValue,
    // oldValue, ...) and therefore did nothing at all on a new record
    // while reporting no error anywhere. The platform's own dispatcher
    // ends with
    //
    //     clientScriptOnChange(elementName, eChanged, vOriginal, vChanged, g_form)
    //
    // where vOriginal is read from the hidden
    // sys_original.<table>.<field> input - the value the field held when
    // the FORM LOADED - and vChanged from the live control. A
    // pass-through logger on the registered handler recorded the
    // arguments actually delivered during real keystrokes on a NEW
    // record as
    //
    //     ["<SELECT>", "", "Person", "false", "false"]
    //
    // so the second argument is "" on a new record (nothing was stored
    // at load) and the third carries the discriminator the user just
    // chose. With the names transposed, this function's `newValue` was
    // always "" on an insert and it returned at the empty-discriminator
    // guard below every single time; on a STORED record `newValue` would
    // instead have been pinned to the load-time party_type, which would
    // have cleared the reference belonging to the OLD branch - wiping
    // the field the user had just revealed. Both failure modes are
    // removed by naming the parameters in the order they arrive.

    // The discriminator values, spelled as the Choice VALUEs in
    // ../choices/sys_choice_case_party_party_type.xml, mapped to the
    // reference column each one makes INAPPLICABLE. The map is the
    // client-side half of the PARTY_TYPE_FIELDS map in
    // ../business_rules/x_casemgmt_validate_case_party_integrity.xml and
    // is deliberately written the same way, so the two halves of AAP
    // Section 0.5.7's exactly-one-of contract are recognisably one
    // contract and a new party_type cannot be added to one half alone.
    var STALE_REFERENCE = {
        'Person': 'organization',
        'Organization': 'person'
    };

    // isLoading is true while the platform renders a record and replays
    // its stored values through onChange. Nothing the user did caused
    // that, so nothing may be cleared: a stored Person party carries an
    // empty organization legitimately, and a stored row must never be
    // mutated by being looked at - which is one of the reasons this is
    // not a UI Policy action (a policy action applies on load).
    if (isLoading) {
        return;
    }

    // An empty discriminator states nothing about which reference is
    // inapplicable, and blanking the choice on the way to re-picking the
    // same branch must not destroy the value that branch needs. The
    // Business Rule refuses an empty party_type on its own ("Party Type
    // is mandatory: choose Person or Organization."), so nothing is lost
    // by leaving this case alone.
    if (newValue === '') {
        return;
    }

    // ALLOWLIST, NOT A LOOKUP MISS. An unrecognised discriminator names
    // no inapplicable column, so there is nothing this script may clear;
    // the row belongs to the Business Rule, which refuses an undeclared
    // party_type outright. hasOwnProperty rather than a bare property
    // read so that a value naming an Object.prototype member
    // ('constructor', 'toString') cannot be mistaken for a declared
    // party_type.
    if (!Object.prototype.hasOwnProperty.call(STALE_REFERENCE, newValue)) {
        return;
    }

    var stale = STALE_REFERENCE[newValue];

    // A view may omit the field, and a field-level ACL may remove it
    // from the form entirely. Either way there is nothing to clear, and
    // asking the platform to write a field that is not on the form logs
    // a client error.
    if (!g_form.hasField(stale)) {
        return;
    }

    // A reference field on the classic form has TWO submit inputs: the
    // value input carrying the sys_id and sys_display.<table>.<field>
    // carrying the text the user sees. The display input can also hold
    // text the user typed without picking a row, with no value behind
    // it, which the server will still try to resolve. Both are therefore
    // read before deciding there is nothing to do.
    var displayBox = g_form.getDisplayBox(stale);
    var staleValue = g_form.getValue(stale);
    var staleDisplay = displayBox ? displayBox.value : '';

    // Already clean - the common case, e.g. the first time a
    // discriminator is chosen on a new record. Returning here keeps the
    // script from marking an untouched field as changed.
    if (!staleValue && !staleDisplay) {
        return;
    }

    // The supported API, called with an explicit empty display value.
    // The three-argument form sets value and display value together, so
    // it both guarantees the display text goes with the value (the
    // two-argument form asks the server to resolve a display value for
    // the value it was given) and avoids that round trip. This is what
    // takes the stale sys_id out of the POST.
    g_form.setValue(stale, '', '');

    // Then the one case the supported API cannot be relied on to finish:
    // text the user typed into the reference input without selecting a
    // row was never a VALUE, so clearing the value need not clear it.
    // Writing the display input directly is the same narrow, documented
    // DOM touch ./x_casemgmt_case_closed_readonly_enforce.xml uses for
    // choice controls, and it is guarded so a field the platform renders
    // without an addressable display input is left alone.
    if (displayBox && displayBox.value) {
        displayBox.value = '';
    }
}
